class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # dp[i] is a bitset of sums achievable for index i
        # using a subset of processed queries that cover index i.
        dp = [1] * n

        # We only need to keep sums up to nums[i].
        masks = [(1 << (x + 1)) - 1 for x in nums]

        if all(x == 0 for x in nums):
            return 0

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                # Either skip this query for index i, or take it.
                dp[i] = (dp[i] | (dp[i] << val)) & masks[i]

            if all(((dp[i] >> nums[i]) & 1) for i in range(n)):
                return k

        return -1

