    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)

        # All substrings of t, including the empty substring.
        t_parts = [(l - k, t[k:l]) for k in range(m + 1) for l in range(k, m + 1)]
        t_parts.sort(reverse=True)  # Sort by length descending to allow early breaking.

        ans = 0

        # Enumerate every substring of s, including the empty substring.
        for i in range(n + 1):
            for j in range(i, n + 1):
                left = s[i:j]
                left_len = j - i

                for right_len, right in t_parts:
                    total_len = left_len + right_len

                    # Since t_parts is sorted by length descending, no later
                    # right substring can produce a longer palindrome.
                    if total_len <= ans:
                        break

                    candidate = left + right
                    if candidate == candidate[::-1]:
                        ans = total_len

        return ans

